function loadOn(d){inflight=Math.max(0,inflight+d);const g=document.getElementById("gload");if(g)g.hidden=!inflight}
function netErr(e){const m=String(e&&e.message||e);return /^(timeout|network|blocked)$/.test(m)?"\u05d4\u05e9\u05e8\u05ea \u05dc\u05d0 \u05e2\u05d5\u05e0\u05d4 ("+m+"). \u05d9\u05d9\u05ea\u05db\u05df \u05e9\u05d4\u05e1\u05d9\u05e0\u05d5\u05df \u05d1\u05d0\u05d9\u05e0\u05d8\u05e8\u05e0\u05d8 \u05d7\u05d5\u05e1\u05dd \u05d0\u05ea script.google.com \u2013 \u05e0\u05e1\u05d5 \u05e9\u05d5\u05d1 \u05d0\u05d5 \u05d4\u05d9\u05db\u05e0\u05e1\u05d5 \u05d3\u05e8\u05da \u05d4\u05e7\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e8\u05d2\u05d9\u05dc \u05e9\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea.":m}
