const TB={};
function tbl(n){return TB[n]||(TB[n]={docs:new Map(),v:null,ls:new Set(),loaded:false,req:false})}
function emit(n){tbl(n).ls.forEach(f=>{try{f()}catch(e){console.error(e)}})}
const emitQ=new Set();let emitT=null;
function scheduleEmit(n){emitQ.add(n);if(!emitT)emitT=setTimeout(()=>{emitT=null;const a=[...emitQ];emitQ.clear();a.forEach(emit)},30)}
function setDocs(n,arr,v){const t=tbl(n);
  if(arr&&arr.delta){const keep=new Set(arr.ids),m=new Map();t.docs.forEach((d,id)=>{if(keep.has(id))m.set(id,d)});arr.rows.forEach(d=>m.set(d._id,d));t.docs=m}
  else t.docs=new Map(arr.map(d=>[d._id,d]));
  let mx=arr&&arr.delta?(t.maxu||""):"";(arr&&arr.delta?arr.rows:arr).forEach(d=>{if((d.updated_date||"")>mx)mx=d.updated_date});t.maxu=mx;t.v=v;t.loaded=true;emit(n)}
const loadQ=new Set();let loadT=null;
function want(n){const t=tbl(n);if(t.loaded||t.req)return;t.req=true;loadQ.add(n);clearTimeout(loadT);loadT=setTimeout(flushLoad,10)}
async function flushLoad(){const tables=[...loadQ];loadQ.clear();if(!tables.length)return;
  try{const r=await call("load",{tables});tables.forEach(n=>{tbl(n).req=false;setDocs(n,r.docs[n]||[],r.v[n])})}
  catch(e){tables.forEach(n=>tbl(n).req=false);if(e.code!=="auth")banner("\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d8\u05e2\u05d5\u05df \u05e0\u05ea\u05d5\u05e0\u05d9\u05dd: "+e.message,"bad")}}
function sub(n,fn){const t=tbl(n);t.ls.add(fn);want(n);if(t.loaded)setTimeout(fn,0);return()=>t.ls.delete(fn)}
function waitLoaded(n){return new Promise(r=>{if(tbl(n).loaded)return r();const f=()=>{if(tbl(n).loaded){tbl(n).ls.delete(f);r()}};tbl(n).ls.add(f);want(n)})}
let syncing=false,connWarn=false;
const inflightT=new Map();
const pendingFor=n=>wq.some(o=>o.t===n)||inflightT.has(n);
async function syncNow(){
  if(syncing||!TOKEN||!db)return;const v={};Object.entries(TB).forEach(([n,t])=>{if(t.loaded&&t.ls.size)v[n]=t.v});
  if(!Object.keys(v).length)return;syncing=true;const since={};Object.keys(v).forEach(n=>{const t=TB[n];if(t.maxu&&t.docs.size>300)since[n]=t.maxu});
  try{const r=await call("sync",{v,since});Object.keys(r.docs).forEach(n=>{if(!pendingFor(n))setDocs(n,r.docs[n],r.v[n])});if(connWarn){connWarn=false;banner("")}}
  catch(e){if(e.code==="unavailable"){connWarn=true;banner("\u05d0\u05d9\u05df \u05d7\u05d9\u05d1\u05d5\u05e8 \u05dc\u05e9\u05e8\u05ea \u05db\u05e8\u05d2\u05e2. \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05d9\u05d9\u05e9\u05de\u05e8\u05d5 \u05db\u05e9\u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d9\u05d7\u05d6\u05d5\u05e8.","warn")}}
  finally{syncing=false}}
setInterval(()=>{if(document.visibilityState==="visible")syncNow()},20000);
