const wq=[];let wT=null;
function queueWrite(op){return new Promise((res,rej)=>{op.res=res;op.rej=rej;wq.push(op);applyLocal(op);clearTimeout(wT);wT=setTimeout(flushWrites,wq.length>=400?0:120)})}
function applyLocal(o){const t=tbl(o.t),cur=t.docs.get(o.id),now=new Date().toISOString();
  if(o.op==="delete")t.docs.delete(o.id);
  else if(o.op==="set")t.docs.set(o.id,{...o.data,_id:o.id,created_date:cur?.created_date||now,created_by:cur?.created_by||uid,updated_date:now,updated_by:uid});
  else t.docs.set(o.id,{...(cur||{}),...o.data,_id:o.id,updated_date:now,updated_by:uid});
  scheduleEmit(o.t)}
async function flushWrites(){
  if(!wq.length)return;const batch=wq.splice(0,500);if(wq.length)wT=setTimeout(flushWrites,0);
  window.onbeforeunload=()=>"\u05d9\u05e9 \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05e0\u05e9\u05de\u05e8\u05d9\u05dd";
  const ts=[...new Set(batch.map(o=>o.t))];ts.forEach(n=>inflightT.set(n,(inflightT.get(n)||0)+1));let stale=false;
  try{const r=await call("batch",{ops:batch.map(({t,op,id,data,expect})=>expect?{t,op,id,data,expect}:{t,op,id,data})});
    const bad=new Map();ts.forEach(n=>(r[n]?.conflicts||[]).forEach(c=>bad.set(n+"|"+c.id,c)));
    ts.forEach(n=>{const t=tbl(n);if(r[n]&&t.v===r[n].before&&!(r[n].conflicts||[]).length)t.v=r[n].after;else{t.v="stale";stale=true}});
    batch.forEach(o=>{const c=bad.get(o.t+"|"+o.id);c?o.rej({code:"conflict",message:`${names[c.by]||c.by||"\u05de\u05e9\u05ea\u05de\u05e9 \u05d0\u05d7\u05e8"} \u05e2\u05d3\u05db\u05df/\u05d4 \u05d0\u05ea \u05d4\u05e8\u05e9\u05d5\u05de\u05d4 \u05d1\u05d9\u05e0\u05ea\u05d9\u05d9\u05dd`,conflict:c}):o.res()})}
  catch(e){batch.forEach(o=>o.rej(e));ts.forEach(n=>tbl(n).v="stale");stale=true;if(e.code!=="auth"&&e.code!=="unavailable")toast(e.message||"\u05d4\u05e9\u05de\u05d9\u05e8\u05d4 \u05e0\u05db\u05e9\u05dc\u05d4")}
  finally{ts.forEach(n=>{const c=inflightT.get(n)-1;c?inflightT.set(n,c):inflightT.delete(n)});if(!wq.length&&!inflightT.size)window.onbeforeunload=null;if(stale)setTimeout(syncNow,50)}}

const rid=()=>{const a=new Uint8Array(14);crypto.getRandomValues(a);return [...a].map(b=>"abcdefghijklmnopqrstuvwxyz0123456789"[b%36]).join("")};
function colInfo(path){const s=path.split("/");return{t:s.filter((_,i)=>i%2===0).join("__"),p:s.filter((_,i)=>i%2===1).join("/")}}
function docRef(colPath,id){const ci=colInfo(colPath);id=id||rid();
  return{id,path:colPath+"/"+id,
    get:async()=>{await waitLoaded(ci.t);const d=tbl(ci.t).docs.get(id);return{id,exists:!!d,data:()=>d}},
    set:d=>queueWrite({t:ci.t,op:"set",id,data:ci.p?{...d,_p:ci.p}:{...d}}),
    update:(d,expect)=>queueWrite({t:ci.t,op:"update",id,data:{...d},expect:expect||undefined}),
    delete:()=>queueWrite({t:ci.t,op:"delete",id}),
    onSnapshot:next=>sub(ci.t,()=>{const d=tbl(ci.t).docs.get(id);next({id,exists:!!d,data:()=>d})})}}
function cmpv(a,op,v){switch(op){case"==":return a===v;case"!=":return a!==v;case"<":return a<v;case"<=":return a<=v;case">":return a>v;case">=":return a>=v;case"in":return v.includes(a);default:return true}}
function query(colPath,f=[],o=null,l=0){const ci=colInfo(colPath);const flt=ci.p?[["_p","==",ci.p],...f]:f;
  const run=()=>{let a=[...tbl(ci.t).docs.values()].filter(d=>flt.every(([k,op,v])=>cmpv(d[k],op,v)));
    if(o)a.sort((x,y)=>{const p=x[o[0]],q=y[o[0]];return(p<q?-1:p>q?1:0)*(o[1]==="desc"?-1:1)});if(l)a=a.slice(0,l);
    return a.map(d=>({id:d._id,exists:true,data:()=>d}))};
  return{path:colPath,where:(k,op,v)=>query(colPath,[...f,[k,op,v]],o,l),orderBy:(k,d)=>query(colPath,f,[k,d||"asc"],l),limit:n=>query(colPath,f,o,n),
    get:async()=>{await waitLoaded(ci.t);const docs=run();return{docs,size:docs.length,empty:!docs.length}},
    onSnapshot:next=>sub(ci.t,()=>{const docs=run();next({docs,size:docs.length,empty:!docs.length})}),
    doc:id=>docRef(colPath,id),add:async d=>{const r=docRef(colPath);await r.set(d);return r}}}
