function readField(f,pre="f_"){
  const el=$("#"+pre+f.k);if(!el)return undefined;
  if(f.t==="multi")return [...el.querySelectorAll("input:checked")].map(i=>i.value);
  if(f.t==="bool")return el.value==="true";
  if(f.t==="num")return el.value===""?"":Number(el.value);
  if(f.t==="id")return normId(el.value);
  if(f.t==="dt")return el.value?new Date(el.value).toISOString():"";
  if(f.t==="emails")return el.value.split(/[,;\s]+/).map(x=>x.trim().toLowerCase()).filter(Boolean);
  return el.value.trim();
}

