  if(x==="crmLog"){const v=$("#crmNote").value.trim();if(!v)return;const c=S.children.get(id);return busy(el,async()=>{try{await save(E.children,id,{log:[...(c.log||[]),{ts:new Date().toISOString(),by:uid,kind:"note",text:v.slice(0,500)}].slice(-80)});toast("\u05e0\u05e8\u05e9\u05dd \u05d1\u05d9\u05d5\u05de\u05df")}catch(err){toast(err.message)}})}
  if(x==="crmToggle"){const c=S.children.get(id);const on=!isOn(c.is_active);try{await save(E.children,id,{is_active:on,log:[...(c.log||[]),{ts:new Date().toISOString(),by:uid,kind:"sys",text:on?"\u05d4\u05d5\u05d7\u05d6\u05e8/\u05d4 \u05dc\u05e4\u05e2\u05d9\u05dc/\u05d4":"\u05e1\u05d5\u05de\u05df/\u05d4 \u05db\u05dc\u05d0 \u05e4\u05e2\u05d9\u05dc/\u05d4"}].slice(-80)});toast(on?"\u05e1\u05d5\u05de\u05df/\u05d4 \u05db\u05e4\u05e2\u05d9\u05dc/\u05d4":"\u05e1\u05d5\u05de\u05df/\u05d4 \u05db\u05dc\u05d0 \u05e4\u05e2\u05d9\u05dc/\u05d4")}catch(err){toast(err.message)}return}
  if(x==="crmDel"){const c=S.children.get(id);modal(`<h2>\u05de\u05d7\u05d9\u05e7\u05ea ${esc(fullName(c))}</h2><p>\u05d4\u05e8\u05e9\u05d5\u05de\u05d4 \u05ea\u05d9\u05de\u05d7\u05e7 \u05dc\u05e6\u05de\u05d9\u05ea\u05d5\u05ea. \u05d0\u05dd \u05d4\u05d9\u05dc\u05d3/\u05d4 \u05e2\u05d6\u05d1/\u05d4, \u05e2\u05d3\u05d9\u05e3 \u05dc\u05e1\u05de\u05df "\u05dc\u05d0 \u05e4\u05e2\u05d9\u05dc/\u05d4" \u2013 \u05db\u05da \u05e0\u05e9\u05de\u05e8\u05ea \u05d4\u05d4\u05d9\u05e1\u05d8\u05d5\u05e8\u05d9\u05d4.</p><div class="row"><button class="btn bad" id="cdGo2">\u05de\u05d7\u05d9\u05e7\u05d4</button><button class="btn" data-close>\u05d1\u05d9\u05d8\u05d5\u05dc</button></div>`);
    $("#cdGo2").onclick=ev=>busy(ev.currentTarget,async()=>{try{await del(E.children,id);CRM.sel=null;closeModal();toast("\u05e0\u05de\u05d7\u05e7")}catch(err){toast(err.message)}});return}
  if(x==="crmExport"||x==="crmBulkExp"){const L=x==="crmBulkExp"?[...CRM.bulk].map(i=>S.children.get(i)).filter(Boolean):crmList();const dk=defOf("children");const ks=dk.fields.filter(f=>f.k!=="row_note").map(f=>f.k);
    audit("\u05d9\u05d9\u05e6\u05d5\u05d0","\u05d9\u05dc\u05d3\u05d9\u05dd","",L.length+" \u05e8\u05e9\u05d5\u05de\u05d5\u05ea");return download("\u05d9\u05dc\u05d3\u05d9\u05dd",[["\u05d2\u05df \u05d1\u05de\u05e2\u05e8\u05db\u05ea",...ks.map(k=>colLabelOf(dk,k))],...L.map(c=>[gName(c.garden_id),...ks.map(k=>show(dk,c,k,true))])],"\u05d9\u05dc\u05d3\u05d9\u05dd")}
  if(x==="crmBulkAll"){crmList().forEach(c=>CRM.bulk.add(c._id));render();return}
