  const all=vals("staff").filter(x=>isOn(x.is_active));const base=all.filter(x=>TCH.f==="teachers"?isTeacher(x):TCH.f==="edu"?isEdu(x):true);
  const un=base.filter(x=>!x.garden_id||!S.gardens?.get(x.garden_id));
  const q=TCH.q.trim().toLowerCase();const L=base.filter(x=>(!TCH.a||(TCH.a==="un"?(!x.garden_id||!S.gardens?.get(x.garden_id)):x.garden_id&&S.gardens?.get(x.garden_id)))&&(!TCH.g||x.garden_id===TCH.g)&&(!q||[x.full_name,x.phone,gName(x.garden_id),(x.roles||[]).join(" ")].join(" ").toLowerCase().includes(q))).sort((a,b)=>String(a.full_name).localeCompare(b.full_name,"he"));
