      <div class="row" style="gap:8px;flex-wrap:wrap">${cur.w?`<label class="row" style="gap:6px"><input type="checkbox" data-plconly="${kind}"${P.only?" checked":""}> \u05e8\u05e7 ${isG?"\u05d1\u05e1\u05de\u05dc \u05d0\u05d7\u05e8":"\u05d2\u05e0\u05d9\u05dd \u05e2\u05dd \u05e1\u05de\u05dc \u05d0\u05d7\u05e8"} (${cur.w})</label>`:""}<input class="search" type="search" data-plcq="${kind}" value="${esc(P.q)}" placeholder="\u05d7\u05d9\u05e4\u05d5\u05e9 \u05d9\u05dc\u05d3/\u05d4\u2026" aria-label="\u05d7\u05d9\u05e4\u05d5\u05e9 \u05d9\u05dc\u05d3/\u05d4" style="max-width:220px"><button class="btn" data-plcx="${kind}|cur">${ico("download")} \u05d9\u05d9\u05e6\u05d5\u05d0 ${isG?"\u05d4\u05d2\u05df":"\u05d4\u05e1\u05de\u05dc"}</button></div></div>
