let BC_FILES=[];
function smRecipients(w){const st=vals("staff").filter(x=>isOn(x.is_active)&&x.email&&x.no_monthly!=="\u05db\u05df");
  const off=vals("office").filter(o=>o.is_active!==false);const offEm=new Set(off.map(o=>lcs(o.email)));
  const isOff=x=>!!x.office_id||offEm.has(lcs(x.email));
  if(w==="office")return st.filter(isOff);if(w==="edu")return st.filter(x=>!isOff(x));
  if(w.startsWith("or:")){const r=w.slice(3),O=off.filter(o=>o.role===r),em=new Set(O.map(o=>lcs(o.email))),ids=new Set(O.map(o=>o._id));return st.filter(x=>em.has(lcs(x.email))||ids.has(x.office_id))}
  if(w.startsWith("r:")){const r=w.slice(2);return st.filter(x=>(x.roles||[]).includes(r))}
  if(w.startsWith("g:"))return st.filter(x=>x.garden_id===w.slice(2));if(w.startsWith("s:"))return st.filter(x=>x._id===w.slice(2));return st}
